const departmentSearch=document.querySelector('#department-search');if(departmentSearch){departmentSearch.addEventListener('input',()=>{const term=departmentSearch.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-department]').forEach(row=>{row.hidden=!row.dataset.department.toLowerCase().includes(term);if(!row.hidden)count++});document.querySelector('#department-count').textContent=`${count} department${count===1?'':'s'} found`})}
